import{_ as e,o as a,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"ADR 模板与复查","description":"","frontmatter":{"title":"ADR 模板与复查","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/adr.md","filePath":"frontend/decisions/adr.md","lastUpdated":1785589115000}'),o={name:"frontend/decisions/adr.md"};function i(c,t,n,l,s,h){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="adr-模板与复查" tabindex="-1">ADR 模板与复查 <a class="header-anchor" href="#adr-模板与复查" aria-label="Permalink to &quot;ADR 模板与复查&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Architecture Decision Record（ADR）是对一个重要技术决定的短记录。它不替代方案文档、会议讨论或实现说明，而是保存当时的问题、约束、结论和后果，让后来者知道“为什么这样做”以及“何时应该重新决定”。</p><h2 id="_1-adr-的职责边界" tabindex="-1">1. ADR 的职责边界 <a class="header-anchor" href="#_1-adr-的职责边界" aria-label="Permalink to &quot;1. ADR 的职责边界&quot;">​</a></h2><h3 id="_1-1-adr-记录决定-不记录全部研究过程" tabindex="-1">1.1 ADR 记录决定，不记录全部研究过程 <a class="header-anchor" href="#_1-1-adr-记录决定-不记录全部研究过程" aria-label="Permalink to &quot;1.1 ADR 记录决定，不记录全部研究过程&quot;">​</a></h3><p>一份 ADR 应能在几分钟内读完。详细性能数据、原型代码和供应商报价可以作为链接附件，正文只保留足以解释结论的证据。</p><h3 id="_1-2-哪些决定需要-adr" tabindex="-1">1.2 哪些决定需要 ADR <a class="header-anchor" href="#_1-2-哪些决定需要-adr" aria-label="Permalink to &quot;1.2 哪些决定需要 ADR&quot;">​</a></h3><p>适合记录的内容包括跨团队接口、数据所有权、框架或平台选择、部署拓扑、不可逆迁移和长期采购。不适合的内容包括格式化规则、局部函数实现和没有其他候选项的强制合规要求。</p><h3 id="_1-3-adr-与-rfc-的区别" tabindex="-1">1.3 ADR 与 RFC 的区别 <a class="header-anchor" href="#_1-3-adr-与-rfc-的区别" aria-label="Permalink to &quot;1.3 ADR 与 RFC 的区别&quot;">​</a></h3><p>RFC 用于在决定前征求意见，通常包含更多候选设计；ADR 保存决定后的稳定摘要。小团队可以在同一文件中先标记 <code>proposed</code>，通过后改为 <code>accepted</code>，但仍要区分讨论意见和最终结论。</p><h2 id="_2-状态与生命周期" tabindex="-1">2. 状态与生命周期 <a class="header-anchor" href="#_2-状态与生命周期" aria-label="Permalink to &quot;2. 状态与生命周期&quot;">​</a></h2><h3 id="_2-1-推荐状态" tabindex="-1">2.1 推荐状态 <a class="header-anchor" href="#_2-1-推荐状态" aria-label="Permalink to &quot;2.1 推荐状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><code>proposed</code></td><td>正在评审，尚不能作为工程约束</td></tr><tr><td><code>accepted</code></td><td>已采用，后续实现应遵守</td></tr><tr><td><code>rejected</code></td><td>已评估但未采用，保留原因避免重复争论</td></tr><tr><td><code>deprecated</code></td><td>仍可能存在，但不用于新范围</td></tr><tr><td><code>superseded</code></td><td>已被新的 ADR 替代，并链接替代记录</td></tr></tbody></table><p>不要直接修改历史 ADR 使其看起来“从未错过”。当结论变化时，新建 ADR，并在旧记录中只补充状态和替代链接。</p><h3 id="_2-2-编号与存放" tabindex="-1">2.2 编号与存放 <a class="header-anchor" href="#_2-2-编号与存放" aria-label="Permalink to &quot;2.2 编号与存放&quot;">​</a></h3><p>使用稳定编号，例如 <code>ADR-0012</code>，文件名可为 <code>0012-use-sse-for-answer-streaming.md</code>。ADR 应与代码放在同一仓库的 <code>docs/adr/</code> 或架构文档目录中，使变更能够经过代码评审并与实现版本关联。</p><h2 id="_3-必填字段" tabindex="-1">3. 必填字段 <a class="header-anchor" href="#_3-必填字段" aria-label="Permalink to &quot;3. 必填字段&quot;">​</a></h2><p>一份可用 ADR 至少包含：</p><table tabindex="0"><thead><tr><th>字段</th><th>要回答的问题</th></tr></thead><tbody><tr><td>标题和状态</td><td>决定是什么，目前是否有效</td></tr><tr><td>日期、负责人、范围</td><td>谁负责，何时生效，影响哪里</td></tr><tr><td>背景</td><td>为什么现在必须决定</td></tr><tr><td>硬约束</td><td>哪些条件不能被权衡</td></tr><tr><td>候选项</td><td>包括维持现状，哪些方案被认真评估</td></tr><tr><td>决定与依据</td><td>选什么，关键证据是什么</td></tr><tr><td>后果</td><td>收益、代价、风险和退出成本</td></tr><tr><td>验证方式</td><td>如何知道决定达到了目标</td></tr><tr><td>复查条件</td><td>哪些信号会触发重新评估</td></tr></tbody></table><p>“使用 WebSocket，因为实时性更好”缺少业务频率、通信方向和运维约束，不能作为有效依据。</p><h2 id="_4-评审方式" tabindex="-1">4. 评审方式 <a class="header-anchor" href="#_4-评审方式" aria-label="Permalink to &quot;4. 评审方式&quot;">​</a></h2><h3 id="_4-1-评审问题而非个人偏好" tabindex="-1">4.1 评审问题而非个人偏好 <a class="header-anchor" href="#_4-1-评审问题而非个人偏好" aria-label="Permalink to &quot;4.1 评审问题而非个人偏好&quot;">​</a></h3><p>评审者应依次检查：问题是否真实、硬约束是否完整、候选是否公平、证据能否复现、负面后果是否被接受。先争论工具排名，会掩盖真正的前提分歧。</p><h3 id="_4-2-记录异议和未决风险" tabindex="-1">4.2 记录异议和未决风险 <a class="header-anchor" href="#_4-2-记录异议和未决风险" aria-label="Permalink to &quot;4.2 记录异议和未决风险&quot;">​</a></h3><p>不必追求所有人完全同意。对没有阻止决定但值得保留的异议，可记录为“已知风险”，同时指定验证指标和负责人。这样异议可以被数据验证，而不是在会议结束后消失。</p><h2 id="_5-场景化结论" tabindex="-1">5. 场景化结论 <a class="header-anchor" href="#_5-场景化结论" aria-label="Permalink to &quot;5. 场景化结论&quot;">​</a></h2><p>以下案例是 AI 客服页面的答案流式传输：浏览器只需接收服务端事件；普通请求仍使用 HTTPS；公司网关已经验证 SSE 可透传；首字延迟目标为 1 秒；不要求浏览器向同一连接发送业务消息。</p><p>在这些约束下，SSE 比 WebSocket 更贴合单向数据流，且更容易复用现有 HTTP 鉴权和可观测链路。若未来增加低延迟双向语音或协同编辑，这个结论不再适用。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>采用 ADR 会增加少量写作和评审成本，也会暴露团队对目标和证据的分歧。它带来的收益是减少重复调研、支持新人理解历史、让迁移和复查有依据。</p><p>ADR 仓库本身也需要治理：指定所有者、在变更模板或架构规则时更新索引、定期处理长期停留在 <code>proposed</code> 的记录。没有人维护的 ADR 会迅速变成过期文档。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>不要为每个依赖升级写 ADR；只有升级改变公开契约或运行边界时才需要。</li><li>不要用 ADR 代替安全评审、数据保护评估或采购审批。</li><li>不要只留下最终工具名称；缺少约束和后果的记录不能防止重复争论。</li><li>不要把未来计划伪装成已接受决定，计划应进入技术路线或待办。</li></ul><h2 id="_8-填写完成的-adr" tabindex="-1">8. 填写完成的 ADR <a class="header-anchor" href="#_8-填写完成的-adr" aria-label="Permalink to &quot;8. 填写完成的 ADR&quot;">​</a></h2><blockquote><p><strong>ADR-0012：客服回答流采用 SSE</strong></p><ul><li><strong>状态</strong>：accepted</li><li><strong>日期</strong>：2026-08-01</li><li><strong>负责人</strong>：客服平台前端负责人</li><li><strong>范围</strong>：Web 客服对话的文本与工具进度事件，不覆盖语音和坐席协同。</li></ul></blockquote><p><strong>背景</strong>：当前接口等待完整回答后返回，P75 首次可见内容为 6.4 秒。目标是在模型产生首段文本后 1 秒内呈现，并允许用户取消生成。</p><p><strong>硬约束</strong>：沿用现有 HTTPS 网关和 Session Cookie；企业代理必须可用；消息只从服务端流向浏览器；断线后允许重新发起本次回答，不要求逐事件续传。</p><p><strong>候选项</strong>：普通轮询、SSE、WebSocket。轮询产生额外请求且无法稳定达到首字目标；WebSocket 能满足性能，但引入独立连接鉴权、心跳和网关运维。SSE 满足单向流和延迟要求。</p><p><strong>决定</strong>：答案文本、工具阶段和结束信号使用 SSE；创建会话、提交问题和取消仍使用普通 HTTP。客户端以显式 <code>done</code> 或错误事件结束状态，不依赖连接关闭推断业务完成。</p><p><strong>后果</strong>：可以复用 HTTP 基础设施，调试简单；需要处理代理缓冲、连接中断和每用户并发限制；不支持在同一连接上发送浏览器消息。</p><p><strong>验证</strong>：灰度 10% 流量两周，要求首段内容 P75 小于 1 秒、异常结束率低于 0.5%、网关 5xx 不高于旧接口基线。</p><p><strong>退出路径</strong>：流事件使用与传输无关的 <code>{ type, id, data }</code> 契约；若迁移 WebSocket，领域事件无需重写。</p><p><strong>复查条件</strong>：出现双向低延迟需求；企业代理导致异常率超过 1%；单用户需要超过 6 条并发流；浏览器需从断点精确续传。</p><h2 id="_9-复查与替代" tabindex="-1">9. 复查与替代 <a class="header-anchor" href="#_9-复查与替代" aria-label="Permalink to &quot;9. 复查与替代&quot;">​</a></h2><p>复查不是定期重写所有 ADR。团队可每季度扫描状态，同时在以下事件发生时主动复查：指标连续越界、关键假设失效、供应商或标准停止支持、组织边界变化、出现无法接受的维护成本。</p><p>若 SSE 决定被 WebSocket 替代，应新增 <code>ADR-0027</code>，在 <code>ADR-0012</code> 中将状态改为 <code>superseded by ADR-0027</code>。历史原因、原始证据和当时接受的代价继续保留。</p>',46)])])}const u=e(o,[["render",i]]);export{b as __pageData,u as default};
